//! Interface language, following the reference's `Locale.tsx`.
//! - pt-BR strings are the keys.
//! - English comes from the reference catalogues (`assets/i18n/en.json`, generated by
//!   `tools/native-i18n.ts`) plus the native-only phrases below.
//! - "Idioma do navegador" follows the Windows display language: Portuguese gives pt-BR,
//!   anything else English, as the reference does with `navigator.languages`.
//! - User content (bar and layout names) is never translated.
use std::{
    collections::HashMap,
    sync::{
        OnceLock,
        atomic::{AtomicU8, Ordering},
    },
};

use geppio_core::json::{self, Json};
use gpui::{App, Global, SharedString};

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Preference {
    #[default]
    Auto,
    PtBr,
    En,
}

impl Preference {
    pub fn parse(value: &str) -> Option<Self> {
        match value {
            "auto" => Some(Self::Auto),
            "pt-BR" => Some(Self::PtBr),
            "en" => Some(Self::En),
            _ => None,
        }
    }
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::PtBr => "pt-BR",
            Self::En => "en",
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Locale {
    #[default]
    PtBr,
    En,
}

/// The app-wide language choice.
#[derive(Clone, Copy, Debug, Default)]
pub struct I18n {
    pub preference: Preference,
    pub system: Locale,
}

impl Global for I18n {}

impl I18n {
    pub fn locale(&self) -> Locale {
        match self.preference {
            Preference::Auto => self.system,
            Preference::PtBr => Locale::PtBr,
            Preference::En => Locale::En,
        }
    }
}

/// Phrases that exist only in the native host.
const NATIVE: &[(&str, &str)] = &[
    (
        "Composição salva incompatível ou ilegível. O arquivo foi preservado e a edição fica bloqueada até a recuperação pelas Configurações.",
        "The saved composition is incompatible or unreadable. The file was preserved and editing stays locked until recovery in Settings.",
    ),
    (
        "Widget adicionado. Salve ou cancele.",
        "Widget added. Save or cancel.",
    ),
    (
        "Widget removido. Desfazer o restaura nesta sessão.",
        "Widget removed. Undo restores it in this session.",
    ),
    ("Ação desfeita.", "Action undone."),
    (
        "Conclua ou cancele a edição antes de importar.",
        "Finish or cancel editing before importing.",
    ),
    ("Ação refeita.", "Action redone."),
];

fn english() -> &'static HashMap<String, String> {
    static EN: OnceLock<HashMap<String, String>> = OnceLock::new();
    EN.get_or_init(|| {
        let mut map = HashMap::new();
        if let Ok(Json::Object(entries)) = json::parse(include_str!("../assets/i18n/en.json")) {
            for (key, value) in entries.iter() {
                if let Some(text) = value.as_str() {
                    map.insert(key.to_owned(), text.to_owned());
                }
            }
        }
        for (key, value) in NATIVE {
            map.insert((*key).to_owned(), (*value).to_owned());
        }
        map
    })
}

/// A translator bound to one locale; cheap to copy into render helpers.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Tr(pub Locale);

impl Tr {
    /// The phrase in the current language (the key itself when untranslated).
    pub fn t(self, key: &str) -> SharedString {
        match self.0 {
            Locale::PtBr => SharedString::from(key.to_owned()),
            Locale::En => SharedString::from(
                english()
                    .get(key)
                    .cloned()
                    .unwrap_or_else(|| key.to_owned()),
            ),
        }
    }
    /// The phrase with `{0}`, `{1}`… replaced by `params`.
    /// Parameters are substituted in one pass, so a parameter that contains `{1}` stays
    /// literal.
    pub fn f(self, key: &str, params: &[&str]) -> SharedString {
        let template = self.t(key);
        let mut out = String::with_capacity(template.len());
        let mut rest = template.as_ref();
        while let Some(open) = rest.find('{') {
            out.push_str(&rest[..open]);
            let tail = &rest[open + 1..];
            let close = tail.find('}');
            let index = close.and_then(|c| tail[..c].parse::<usize>().ok());
            match (close, index.and_then(|i| params.get(i))) {
                (Some(c), Some(p)) => {
                    out.push_str(p);
                    rest = &tail[c + 1..];
                }
                _ => {
                    out.push('{');
                    rest = tail;
                }
            }
        }
        out.push_str(rest);
        SharedString::from(out)
    }
}

/// The translator for the current language.
pub fn tr(cx: &App) -> Tr {
    Tr(cx.try_global::<I18n>().map_or(Locale::PtBr, I18n::locale))
}

/// The language of the one window, mirrored for render helpers that have no `App`.
static CURRENT: AtomicU8 = AtomicU8::new(0);

/// Installs the language choice as the app global and the render-helper mirror.
pub fn install(cx: &mut App, i18n: I18n) {
    CURRENT.store(
        if i18n.locale() == Locale::En { 1 } else { 0 },
        Ordering::Relaxed,
    );
    cx.set_global(i18n);
}

/// The phrase in the current language, for render helpers.
pub fn t(key: &str) -> SharedString {
    Tr(if CURRENT.load(Ordering::Relaxed) == 1 {
        Locale::En
    } else {
        Locale::PtBr
    })
    .t(key)
}

/// The system language: Portuguese display language → pt-BR, otherwise English.
pub fn system_locale() -> Locale {
    if crate::platform::portuguese_ui() {
        Locale::PtBr
    } else {
        Locale::En
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn english_comes_from_the_reference_catalogue() {
        let en = Tr(Locale::En);
        assert_eq!(en.t("Configurações"), "Settings");
        assert_eq!(en.t("Notificações"), "Notifications");
        assert_eq!(en.t("Texto que não existe"), "Texto que não existe");
        assert_eq!(Tr(Locale::PtBr).t("Configurações"), "Configurações");
        assert_eq!(
            Tr(Locale::PtBr).f("Excluir {0}?", &["Foco"]),
            "Excluir Foco?"
        );
        assert!(english().len() > 800);
        assert_eq!(Tr(Locale::PtBr).f("{0} e {1}", &["{1}", "b"]), "{1} e b");
        assert_eq!(Preference::parse("pt-BR"), Some(Preference::PtBr));
        assert_eq!(Preference::parse("fr"), None);
    }
}
